    if x1 >= BN254_PRIME || y1 >= BN254_PRIME || x2 >= BN254_PRIME || y2 >= BN254_PRIME {
        return Option::None;
    }
    // snip
}

    fn exec(input: Span<u8>) -> Result<(u64, Span<u8>), EVMError> {
        let gas = BASE_COST;

        // snip

        let (x, y) = match ec_add(x1, y1, x2, y2) {
            Option::Some((x, y)) => { (x, y) },
            Option::None => {
                return Result::Err(EVMError::InvalidParameter('invalid ec_add parameters'));//@audit
            },
        };

        let mut result_bytes = array![];
        // Append x to the result bytes.
        let x_bytes = x.to_be_bytes_padded();
        result_bytes.append_span(x_bytes);
        // Append y to the result bytes.
        let y_bytes = y.to_be_bytes_padded();
        result_bytes.append_span(y_bytes);

        return Result::Ok((gas, result_bytes.span()));
    }
```

As hinted by the `@audit` tags, if invalid parameters are passed, the execution gracefully returns an error and only when the datas are valid do we get to the flow of `return Result::Ok((gas, result_bytes.span()));`, however regardless of the data being valid or not the `BASE_COST` should still be charged.

As hinted earlier this is the same case with `ec_mul#exec()` see [ec_mul.cairo#L54-L87](https://github.com/kkrt-labs/kakarot-ssj/blob/d4a7873d6f071813165ca7c7adb2f029287d14ca/crates/evm/src/precompiles/ec_operations/ec_mul.cairo#L54-L87)

